import React from 'react';
import { motion } from 'framer-motion';
import './Hero.css';

const Hero = () => {
  return (
    <section className="hero">
      <div className="hero-container">
        <motion.div
          className="hero-content"
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
        >
          <h1 className="hero-title">Smart Healthcare for Smart Students</h1>
          <p className="hero-subtitle">
            Experience seamless health management with MediCampus. Book appointments,
            track queues, access digital records, and manage certificates all in one place.
          </p>
          <div className="hero-buttons">
            <motion.button
              className="btn-primary"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Book Appointment
            </motion.button>
            <motion.button
              className="btn-secondary"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              View Queue
            </motion.button>
          </div>
        </motion.div>
        <motion.div
          className="hero-illustration"
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
        >
          {/* Placeholder for illustration */}
          <div className="illustration-placeholder">
            <div className="pulse"></div>
            <div className="pulse delay"></div>
          </div>
        </motion.div>
      </div>
      <div className="hero-bg">
        <div className="wave"></div>
      </div>
    </section>
  );
};

export default Hero;
